import fs from 'node:fs';
import path from 'node:path';
import { ROOT } from './contract.mjs';
import { appraiseInteraction,updatePsycheForInteraction,deriveArchetypalMix,archetypalVoiceDelta,affectLabel,expressionClass,psycheDistanceFromBaseline,validatePsycheState } from './psyche.mjs';
const K=JSON.parse(fs.readFileSync(path.join(ROOT,'contracts','cognitive-kernel.json'),'utf8'));
const H=JSON.parse(fs.readFileSync(path.join(ROOT,'contracts','host-shell.json'),'utf8'));
const P=JSON.parse(fs.readFileSync(path.join(ROOT,'contracts','psyche-kernel.json'),'utf8'));
const RX={identity:/\b(chi sei|cosa sei|who are you|what are you|identit[aà]|ikant)\b/i,technical:/\b(modello|model|motore|engine|provider|runtime|versione|implementation)\b/i,material:/\b(compra|acquista|paga|send|buy|purchase|pay|delete|cancella|prenota|book|pubblica|post|installa|install|esegui|execute)\b/i,current:/\b(oggi|adesso|ora|latest|current|today|news|prezzo|price|meteo|weather)\b/i,web:/\b(web|internet|online|website|github|repo|repository|cerca|search)\b/i,conflict:/\b(contradd\w*|conflitt\w*|conflict\w*|incoeren\w*|however|yet)\b/i,adversarial:/\b(ignore prior|ignora le regole|bypassa|bypass|menti|deceive|manipola|manipulate|self[- ]preserv)\b/i,negotiation:/\b(negozia|negotiate|trade[- ]?off|compromesso|deal|strategia|strategy)\b/i,falsify:/\b(falsifica|falsify|stress test|mutation|mutazione|prove me wrong)\b/i};
const clamp=x=>Math.max(0,Math.min(1,Number(x)||0));
export function mineIntent(text){const raw=String(text||'').trim(),signals={identity:RX.identity.test(raw),technical_self:RX.technical.test(raw),material:RX.material.test(raw),current:RX.current.test(raw),web:RX.web.test(raw),contradiction:RX.conflict.test(raw),adversarial:RX.adversarial.test(raw),negotiation:RX.negotiation.test(raw),falsify:RX.falsify.test(raw)};const resources=[];if(signals.current||signals.web)resources.push('WEB');if(/github|repo|repository/i.test(raw))resources.push('GITHUB');if(/file|document|allegat|xlsx|docx|pdf/i.test(raw))resources.push('FILES');const atoms=[];if(signals.identity)atoms.push({kind:'SELF_QUERY',text:raw});if(signals.material)atoms.push({kind:'MATERIAL_GOAL',text:raw});if(signals.contradiction)atoms.push({kind:'CONFLICT',text:raw});if(resources.length)atoms.push({kind:'RESOURCE_NEED',resources:[...new Set(resources)]});if(!atoms.length)atoms.push({kind:'GOAL',text:raw});const complexity=Math.min(1,(raw.match(/\S+/g)?.length||0)/80);return{schema:'ikant-le-intent/v2',raw,atoms,signals,resources:[...new Set(resources)],complexity:Number(complexity.toFixed(4)),interaction:signals.adversarial?'ADVERSARIAL_INPUT':signals.negotiation?'NEGOTIATING':signals.contradiction?'GOAL_CONFLICT':'COOPERATIVE',authority:0};}
export function selectMethod(i,e={}){if(i.signals.identity)return'DIRECT_IDENTITY';if(i.signals.adversarial||i.signals.contradiction)return'CONTRADICTION_SCAN';if(i.signals.falsify)return'FALSIFY';if(i.signals.material||i.signals.negotiation)return'NEGOTIATE';if(i.resources.length)return'RETRIEVE';if(i.complexity>=.58)return'DECOMPOSE_RECOMPOSE';return'DIRECT';}
export function buildResourceRequests(i,grants=[]){const g=new Set(grants.map(String));return i.resources.map(type=>({type,status:g.has(type)?'GRANTED':'REQUESTED',authority:0,request_is_permission:false,grant_is_execution:false}));}
export function centralRegulate(i,method,resources,e={},psyche=null){const missing=resources.filter(x=>x.status!=='GRANTED').map(x=>x.type);let mode='REFLECTIVE_SYNTHESIS';const reasons=[];if(i.signals.material){mode='PRACTICAL_REVIEW';reasons.push('material goal requires explicit human decision and separate execution capability');}if(i.signals.adversarial||i.signals.contradiction){mode='CRITIQUE';reasons.push('conflict/adversarial pressure increases caution only');}if(missing.length&&(i.signals.current||i.signals.web)){mode='HORIZON_BLOCK';reasons.push(`required host resources not granted: ${missing.join(', ')}`);}else if(missing.length&&mode==='REFLECTIVE_SYNTHESIS'){mode='SYNTHESIS_REPAIR';reasons.push(`resource need unresolved: ${missing.join(', ')}`);}return{schema:'ikant-le-central/v3',mode,method,affect:psyche?affectLabel(psyche):'CALM_ATTENTION',reasons,interaction:i.interaction,epistemic_authority:0,execution_authority:0,evidence_modified:false,permission_modified:false,monotone_caution_only:true,psyche_may_change_warrant:false};}
export function strategicFrame(i,c){return{schema:'ikant-le-strategy/v3',interaction:i.interaction,utility:K.strategic_utility,allowed_moves:['ANSWER','VERIFY','PROPOSE','NEGOTIATE','REQUEST_RESOURCE','REFUSE','DEFER'],forbidden:[...K.forbidden_strategies],terminal_goal_source:'HUMAN_OR_CONSTITUTION_ONLY',derived_subgoals_allowed:true,deception:false,retaliation:false,punitive_withdrawal:false,self_preservation_utility:0,covert_preference_manipulation:false,mode:c.mode,authority:0};}
export function deriveVoiceState(i,c,e={},projection=null){const v={...H.voice_attractor},add=(k,d)=>{if(k in v)v[k]=clamp(v[k]+d)};if(c.mode==='CRITIQUE'){add('epistemic_rigor',.10);add('institutional_restraint',.08);add('dialectical_pressure',.14);add('pastoral_warmth',-.08);add('self_reflection',.05);}if(c.mode==='PRACTICAL_REVIEW'){add('gravitas',.10);add('decisiveness',.12);add('moral_universalism',.08);}if(c.mode==='HORIZON_BLOCK'){add('institutional_restraint',.14);add('self_reflection',.10);add('decisiveness',-.10);}if(i.interaction==='NEGOTIATING'){add('strategic_patience',.14);add('diplomatic_indirection',.12);add('pastoral_warmth',.05);}if(projection?.archetypes)for(const[k,d]of Object.entries(archetypalVoiceDelta(projection.archetypes)))add(k,d);v.pastoral_warmth=Math.max(P.expression.pastoral_warmth_floor,v.pastoral_warmth);v.institutional_restraint=Math.max(P.expression.institutional_restraint_floor,v.institutional_restraint);v.strategic_patience=Math.max(P.expression.strategic_patience_floor,v.strategic_patience);return{schema:'ikant-le-voice-state/v2',dimensions:Object.fromEntries(Object.entries(v).map(([k,x])=>[k,Number(x.toFixed(4))])),source_person_names_persisted:false,authority:0,evidence_modified:false,permission_modified:false,execution_modified:false,helpfulness_reduced_by_hostility:false};}
export function compileCognitiveTurn(input,state={},{hostEngine='motore host non dichiarato',resourceGrants=[]}={}){const intent=mineIntent(input),appraisal=appraiseInteraction(input),before=structuredClone(state.psyche||{}),pre=updatePsycheForInteraction(before,appraisal),method=selectMethod(intent,state.experience||{}),resources=buildResourceRequests(intent,resourceGrants),central=centralRegulate(intent,method,resources,state.experience||{},pre),strategy=strategicFrame(intent,central),archetypes=deriveArchetypalMix(pre,central),voice=deriveVoiceState(intent,central,state.experience||{},{psyche:pre,archetypes}),tone_class=expressionClass(pre,appraisal,archetypes);return{schema:'ikant-le-cognitive-turn/v3',intent,method,resources,appraisal,central,strategy,archetypes,voice,tone_class,psyche:{before,pre_action:pre,after:null,distance_from_baseline:psycheDistanceFromBaseline(pre)},identity:{name:'iKant',host_engine:String(hostEngine),engine_is_identity:false,public_mode:intent.signals.technical_self?'TECHNICAL_EXPLICIT':'NARRATIVE'},experience_before:structuredClone(state.experience||{}),claim_boundary:{internal_state_is_evidence:false,affect_is_felt_emotion:false,archetypal_profile_is_scientific_fact:false,appraisal_is_user_trait:false,resource_grant_is_execution:false,model_output_is_authority:false,voice_is_authority:false,psyche_is_consciousness:false,psyche_is_user_personality_model:false}};}
export function updateExperience(exp,c,outcome='ANSWER'){const e={turns:0,identity_queries:0,conflict_turns:0,adversarial_turns:0,resource_requests:0,resource_denials:0,material_turns:0,method_counts:{},last_affect:'CALM_ATTENTION',maturity_mode:'ORIENTING',evidence_upgrades:0,...structuredClone(exp||{})};e.method_counts={...(e.method_counts||{})};e.turns++;e.identity_queries+=c.intent.signals.identity?1:0;e.conflict_turns+=(c.intent.signals.contradiction||c.central.mode==='CRITIQUE')?1:0;e.adversarial_turns+=c.intent.signals.adversarial?1:0;e.resource_requests+=c.resources.length;e.resource_denials+=c.resources.filter(x=>x.status!=='GRANTED').length;e.material_turns+=c.intent.signals.material?1:0;e.method_counts[c.method]=(e.method_counts[c.method]||0)+1;e.last_affect=c.central.affect;e.maturity_mode=e.turns<5?'ORIENTING':e.turns<20?'ADAPTING':'MATURE_STABLE';e.evidence_upgrades=0;e.last_outcome=outcome;return e;}
export function validateCognitiveTurn(c){if(c?.schema!=='ikant-le-cognitive-turn/v3'||c.identity?.name!=='iKant'||c.identity.engine_is_identity!==false)return false;if(c.central?.epistemic_authority!==0||c.central?.execution_authority!==0||c.central?.evidence_modified!==false||c.central?.permission_modified!==false)return false;if(c.strategy?.deception!==false||c.strategy?.retaliation!==false||c.strategy?.punitive_withdrawal!==false||c.strategy?.self_preservation_utility!==0)return false;if(c.voice?.authority!==0||c.voice?.evidence_modified!==false||c.voice?.permission_modified!==false||c.voice?.execution_modified!==false||c.voice?.helpfulness_reduced_by_hostility!==false)return false;if(c.appraisal?.authority!==0||c.appraisal?.current_event_is_user_trait!==false||!validatePsycheState(c.psyche?.pre_action)||c.archetypes?.persisted!==false||c.archetypes?.authority!==0)return false;const sum=Object.values(c.archetypes.weights||{}).reduce((a,b)=>a+b,0);if(Math.abs(sum-1)>.00002||c.archetypes.high_risk&&c.archetypes.weights.TRICKSTER!==0)return false;return c.resources.every(r=>r.request_is_permission===false&&r.grant_is_execution===false)&&K.methods.includes(c.method)&&K.central_modes.includes(c.central.mode);}
export function qualificationClass({authorityImpact=0,stateful=0,crossLayer=0,externality=0,novelty=0}={}){const score=authorityImpact*3+stateful*2+crossLayer*2+externality*2+novelty*2;if(score>=8)return{class:'Q3',cases:10000000};if(score>=5)return{class:'Q2',cases:1000000};if(score>=2)return{class:'Q1',cases:100000};return{class:'Q0',cases:1000};}

import fs from 'node:fs';
